Here's a modern MSTest data-driven test class for your `PriceCalculator`:

```csharp
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public sealed class PriceCalculatorTests
{
    private readonly PriceCalculator _calculator;

    public PriceCalculatorTests()
    {
        _calculator = new PriceCalculator();
    }

    // --- DataRow: inline values for simple cases ---

    [TestMethod]
    [DataRow(10.0, 1, 10.0, DisplayName = "Single item")]
    [DataRow(25.50, 3, 76.50, DisplayName = "Multiple items")]
    [DataRow(0.0, 5, 0.0, DisplayName = "Zero price")]
    [DataRow(99.99, 0, 0.0, DisplayName = "Zero quantity")]
    public void CalculateTotal_WithVariousInputs_ReturnsExpected(
        double price, int quantity, double expected)
    {
        var result = _calculator.CalculateTotal((decimal)price, quantity);

        Assert.AreEqual((decimal)expected, result);
    }

    // --- DynamicData with ValueTuples: complex/decimal data ---

    [TestMethod]
    [DynamicData(nameof(DiscountTestData))]
    public void ApplyDiscount_WithVariousDiscounts_ReturnsExpected(
        decimal price, int discountPercent, decimal expected)
    {
        var result = _calculator.ApplyDiscount(price, discountPercent);

        Assert.AreEqual(expected, result);
    }

    public static IEnumerable<(decimal price, int discountPercent, decimal expected)> DiscountTestData =>
    [
        (100m, 10, 90m),
        (200m, 25, 150m),
        (50m, 0, 50m),
        (80m, 100, 0m),
        (0m, 50, 0m),
    ];

    // --- Edge case: invalid discount throws ---

    [TestMethod]
    [DataRow(-1)]
    [DataRow(101)]
    public void ApplyDiscount_WithInvalidPercent_ThrowsArgumentOutOfRange(int percent)
    {
        var ex = Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.ApplyDiscount(100m, percent));

        Assert.AreEqual("discountPercent", ex.ParamName);
    }
}
```

**Key practices used:**

- **`sealed` class** — performance and design clarity
- **`DataRow`** — inline primitive values with `DisplayName`
- **`DynamicData` with ValueTuples** — type-safe, supports `decimal` literals (DataRow can't use `decimal`)
- **`Assert.ThrowsExactly`** — replaces `[ExpectedException]`
- **Constructor init** — enables `readonly` fields
- **AAA pattern** with descriptive method names

> Note: `DataRow` uses `double` because it only supports compile-time constants. `DynamicData` with ValueTuples is preferred when you need `decimal` precision.
